   750			       test_bit(TASKLET_STATE_RUN, &op->thrtsklet.state) ||
   751			       hrtimer_active(&op->thrtimer)) {
   752				hrtimer_cancel(&op->thrtimer);
   753				tasklet_kill(&op->thrtsklet);
   754			}
   755		}
   756	
   757		if ((op->frames) && (op->frames != &op->sframe))
