     1	void can_rx_unregister(struct net_device *dev, canid_t can_id, canid_t mask,
     2			       void (*func)(struct sk_buff *, void *), void *data)
     3	{
     4		struct receiver *r = NULL;
     5		struct hlist_head *rl;
     6		struct dev_rcv_lists *d;
     7	
     8		if (dev && dev->type != ARPHRD_CAN)
     9			return;
    10	
    11		spin_lock(&can_rcvlists_lock);
    12	
    13		d = find_dev_rcv_lists(dev);
    14		if (!d) {
    15			pr_err("BUG: receive list not found for "
    16			       "dev %s, id %03X, mask %03X\n",
    17			       DNAME(dev), can_id, mask);
    18			goto out;
    19		}
    20	
    21		rl = find_rcv_list(&can_id, &mask, d);
    22	
    23		/*
    24		 * Search the receiver list for the item to delete.  This should
    25		 * exist, since no receiver may be unregistered that hasn't
    26		 * been registered before.
    27		 */
    28	
    29		hlist_for_each_entry_rcu(r, rl, list) {
    30			if (r->can_id == can_id && r->mask == mask &&
    31			    r->func == func && r->data == data)
    32				break;
    33		}
    34	
    35		/*
    36		 * Check for bugs in CAN protocol implementations using af_can.c:
    37		 * 'r' will be NULL if no matching list item was found for removal.
    38		 */
    39	
    40		if (!r) {
    41			WARN(1, "BUG: receive list entry not found for dev %s, "
    42			     "id %03X, mask %03X\n", DNAME(dev), can_id, mask);
    43			goto out;
    44		}
    45	
    46		hlist_del_rcu(&r->list);
    47		d->entries--;
    48	
    49		if (can_pstats.rcv_entries > 0)
    50			can_pstats.rcv_entries--;
    51	
    52		/* remove device structure requested by NETDEV_UNREGISTER */
    53		if (d->remove_on_zero_entries && !d->entries) {
    54			kfree(d);
    55			dev->ml_priv = NULL;
    56		}
    57	
    58	 out:
    59		spin_unlock(&can_rcvlists_lock);
    60	
    61		/* schedule the receiver item for deletion */
    62		if (r) {
    63			if (r->sk)
    64				sock_hold(r->sk);
